const e = $input.first().json;
const motivos = (Array.isArray(e.motivos) ? e.motivos : []).map(m => `- ${m.tipo}: ${m.mensaje}`).join('
') || '- Sin detalle';
return [{ json: { codigo: e.codigo, nivel: e.nivel, motivos: e.motivos ?? [],
  ficha: `Nombre: ${e.nombre}
Estado académico: ${e.estado_academico}
PGA acumulado: ${e.pga_acumulado ?? 'sin dato'}
`
    + `PGA último periodo: ${e.pga_ultimo_periodo ?? 'sin dato'}
Avance del plan: ${e.porcentaje_avance} %
`
    + `Cursos reprobados: ${e.total_reprobados}
Cursos en curso: ${e.cursos_en_curso}
Alertas de prioridad ALTA:
${motivos}` } }];

const base = $('Preparar datos').item.json;
const texto = String($input.first().json.text ?? '').trim();
return [{ json: { codigo: base.codigo, nivel: base.nivel, motivos: JSON.stringify(base.motivos), mensaje: texto } }];
